import{_ as a,o as r,c as o,ae as t}from"./chunks/framework.Bwt6MOeu.js";const m=JSON.parse('{"title":"Temporal Graph Evolution","description":"","frontmatter":{},"headers":[],"relativePath":"guide/temporal-graph-evolution.md","filePath":"guide/temporal-graph-evolution.md"}'),i={name:"guide/temporal-graph-evolution.md"};function l(n,e,s,p,c,d){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="temporal-graph-evolution" tabindex="-1">Temporal Graph Evolution <a class="header-anchor" href="#temporal-graph-evolution" aria-label="Permalink to &quot;Temporal Graph Evolution&quot;">​</a></h1><p>This guide records how the homepage graph and the full explorer must evolve.</p><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><p>The homepage graph is now moving from a static decorative diagram toward a graph-backed preview. The explorer is already the richer surface and becomes a first-class navigation primitive for the site.</p><h2 id="immediate-direction" tabindex="-1">Immediate direction <a class="header-anchor" href="#immediate-direction" aria-label="Permalink to &quot;Immediate direction&quot;">​</a></h2><p>The homepage graph:</p><ul><li>preview the live graph substrate</li><li>reveal surfaces in temporal rollout/build order</li><li>open the explorer in a new tab when nodes are clicked</li><li>act as a governed preview surface rather than a toy diagram</li></ul><p>The explorer:</p><ul><li>remain the primary graph workspace</li><li>accept focus and mode parameters</li><li>support topology, hybrid, and temporal views</li><li>become the richer control surface for layout, filtering, and exploration</li></ul><h2 id="expanded-topology-next" tabindex="-1">Expanded topology next <a class="header-anchor" href="#expanded-topology-next" aria-label="Permalink to &quot;Expanded topology next&quot;">​</a></h2><p>The next major evolution focuses on the <strong>expanded topology</strong> once it lands. That means the temporal graph does not stop at the current small surface set. It expands to show:</p><ul><li>more surfaces</li><li>more semantic neighborhoods</li><li>release/version changes</li><li>doctrine and architecture linkages</li><li>topology growth over time</li></ul><h2 id="temporal-force-directed-direction" tabindex="-1">Temporal force-directed direction <a class="header-anchor" href="#temporal-force-directed-direction" aria-label="Permalink to &quot;Temporal force-directed direction&quot;">​</a></h2><p>The target is closer to a temporal force-directed graph than a frozen solved layout. Temporal reveal is driven by platform evolution, release order, semantic layering, and expanded topology — not only by arbitrary display order.</p><h2 id="observable-style-control-surface" tabindex="-1">Observable-style control surface <a class="header-anchor" href="#observable-style-control-surface" aria-label="Permalink to &quot;Observable-style control surface&quot;">​</a></h2><p>The graph experience must keep evolving toward a richer control rail:</p><ul><li>mode switching</li><li>focus shortcuts</li><li>topology / hybrid / temporal permutations</li><li>annotation / comment / detail injection where appropriate</li><li>configurable density and layout behaviors</li><li>stronger explorer-first navigation</li></ul><h2 id="documentation-requirement" tabindex="-1">Documentation requirement <a class="header-anchor" href="#documentation-requirement" aria-label="Permalink to &quot;Documentation requirement&quot;">​</a></h2><p>The temporal graph is not just a UI flourish. It is part of the platform’s visible semantic and governance model. The docs therefore describes:</p><ul><li>what the timeline means</li><li>what orderings exist</li><li>how topology expands</li><li>how release/version changes affect the graph</li><li>how explorer interactions map back to the underlying graph substrate</li></ul><h2 id="vector-channel-impact-on-temporal-order" tabindex="-1">Vector-channel impact on temporal order <a class="header-anchor" href="#vector-channel-impact-on-temporal-order" aria-label="Permalink to &quot;Vector-channel impact on temporal order&quot;">​</a></h2><p>Temporal graph order must not remain a simple display hack.</p><p>As the semantic stack matures, temporal evolution is informed by:</p><ul><li>curated rollout order</li><li>semantic cluster emergence</li><li>latent topic expansion</li><li>aligned 23rd-channel changes across LSA23 / LSI23 / LDA23</li><li>graph edge changes from fused representation channels</li></ul><p>In other words, expanded topology must eventually react not only to release order, but also to changes in the semantic basis itself.</p>',25)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
